#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-only
"""For LLMs: verify generated bytes over a paired/encrypted RFCOMM echo link."""
import argparse
import hashlib
import os
import socket
import struct

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--peer', required=True)
parser.add_argument('--channel', required=True, type=int)
parser.add_argument('--packets', type=int, default=2000)
parser.add_argument('--size', type=int, default=1024)
args = parser.parse_args()
if not 1 <= args.channel <= 30 or not 1 <= args.packets <= 10000 or not 96 <= args.size <= 4096:
    raise ValueError('Invalid test geometry')
connection = socket.socket(socket.AF_BLUETOOTH, socket.SOCK_STREAM, socket.BTPROTO_RFCOMM)
connection.setsockopt(274, 4, struct.pack('BB', 2, 0))
connection.settimeout(20)
connection.connect((args.peer, args.channel))
security = connection.getsockopt(274, 4, 2)
# RFCOMM's Linux getter reports level but not key size (unlike L2CAP).
if security[0] < 2:
    raise RuntimeError('Encrypted pairing required')
print('LINUX_RFCOMM_CONNECTED', dict(security=security[0], key_size_reported=security[1]), flush=True)
nonce = os.urandom(32)
digest = hashlib.sha256()
for sequence in range(args.packets):
    seed = nonce + struct.pack('<Q', sequence)
    prefix = b'Gravity Bluetooth data proof ' + seed
    data = prefix + hashlib.shake_256(seed).digest(args.size - len(prefix))
    connection.sendall(data)
    received = bytearray()
    while len(received) < len(data):
        piece = connection.recv(len(data) - len(received))
        if not piece:
            raise RuntimeError('Peer disconnected before echo completed')
        received.extend(piece)
    if received != data:
        raise RuntimeError(f'Bluetooth data mismatch in packet {sequence}')
    digest.update(data)
    if (sequence + 1) % 128 == 0:
        print('LINUX_RFCOMM_PROGRESS', dict(packets=sequence + 1, bytes=(sequence + 1) * args.size), flush=True)
connection.close()
print('LINUX_RFCOMM_DATA_OK', dict(packets=args.packets, bytes=args.packets * args.size,
      sha256=digest.hexdigest(), exact_echo=True), flush=True)
